package com.bn.aliagent.insight.aggregate; import java.time.*; import java.util.*;
public final class HourlyAggregationService { private final AggregationStore store; private final Set<String> processed=new HashSet<>(); public HourlyAggregationService(AggregationStore store){this.store=store;} public AggregateRevision record(String tenant,String metric,int version,Instant occurredAt,ZoneId zone,Map<String,String> dimensions,long numerator,long denominator,String factId){var start=occurredAt.atZone(zone).withMinute(0).withSecond(0).withNano(0).toInstant();var key=new AggregateKey(tenant,metric,version,WindowGranularity.HOURLY,start,new TreeMap<>(dimensions));var prior=store.latest(key);if(!processed.add(factId))return prior.orElseThrow();int previous=prior.map(AggregateRevision::revision).orElse(0);return store.append(AggregateRevision.next(key,previous+1,numerator,denominator),previous);}}
